#include <stdio.h>
#include <stdlib.h>

static int read_int(void) {
    int c = getchar_unlocked();
    while (c <= ' ' && c != EOF) c = getchar_unlocked();

    int value = 0;
    while (c > ' ') {
        value = value * 10 + (c - '0');
        c = getchar_unlocked();
    }
    return value;
}

int main(void) {
    int n = read_int();
    int m = read_int();

    int *head = malloc((size_t)(n + 1) * sizeof(int));
    int *degree = calloc((size_t)(n + 1), sizeof(int));
    int *to = malloc((size_t)(2 * m + 1) * sizeof(int));
    int *next = malloc((size_t)(2 * m + 1) * sizeof(int));

    for (int i = 1; i <= n; i++) head[i] = -1;

    int edge_count = 0;
    for (int i = 0; i < m; i++) {
        int x = read_int();
        int y = read_int();

        to[edge_count] = y;
        next[edge_count] = head[x];
        head[x] = edge_count++;
        degree[x]++;

        to[edge_count] = x;
        next[edge_count] = head[y];
        head[y] = edge_count++;
        degree[y]++;
    }

    char *visited = calloc((size_t)(n + 1), sizeof(char));
    int *stack = malloc((size_t)n * sizeof(int));
    int *vertices = malloc((size_t)n * sizeof(int));
    int *marked = calloc((size_t)(n + 1), sizeof(int));
    int token = 0;

    for (int start = 1; start <= n; start++) {
        if (visited[start]) continue;

        int top = 0;
        int count = 0;
        long long degree_sum = 0;

        stack[top++] = start;
        visited[start] = 1;

        while (top > 0) {
            int u = stack[--top];
            vertices[count++] = u;
            degree_sum += degree[u];

            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (!visited[v]) {
                    visited[v] = 1;
                    stack[top++] = v;
                }
            }
        }

        if (degree_sum < (long long)count * (count - 1)) {
            int candidate = -1;
            for (int i = 0; i < count; i++) {
                if (degree[vertices[i]] < count - 1) {
                    candidate = vertices[i];
                    break;
                }
            }

            token++;
            marked[candidate] = token;
            for (int e = head[candidate]; e != -1; e = next[e]) {
                marked[to[e]] = token;
            }

            for (int i = 0; i < count; i++) {
                int v = vertices[i];
                if (marked[v] != token) {
                    printf("%d %d\n", candidate, v);
                    return 0;
                }
            }
        }
    }

    puts("-1");
    return 0;
}
